pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address target) public {
        // Restrict amount to avoid overflow but keep wide.
        vm.assume(amount > 0 && amount <= address(c).balance);
        // Target must not be the contract itself to avoid self-destruct issues.
        vm.assume(target != address(c));
        // The owner is the contract deployer; ensure target is not the owner to simplify reasoning.
        vm.assume(target != c.owner());

        // Deploy a reverter helper to cause transfer failure.
        Reverter reverter = new Reverter();
        address adversarial = address(reverter);

        // Record initial balances.
        uint256 contractBalanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = c.owner().balance;
        uint256 adversarialBalanceBefore = address(adversarial).balance;

        // Fund the contract with enough ether to send.
        vm.deal(address(c), amount);
        vm.deal(c.owner(), 0); // ensure clean tracking

        // Adversarial callee MUST fail.
        bool ok = true;
        vm.prank(c.owner());
        try c.sendMoney(adversarial, amount) {
        } catch {
            ok = false;
        }

        uint256 contractBalanceAfter = address(c).balance;
        uint256 ownerBalanceAfter = c.owner().balance;
        uint256 adversarialBalanceAfter = address(adversarial).balance;

        // The invariant for the reference contract:
        // When sendMoney is called with a failing callee, it should NOT revert,
        // and the contract balance must decrease by amount (sent out),
        // and the adversarial balance must increase by amount,
        // and the owner balance must remain unchanged.
        // The buggy version (simple transfer) reverts on failure, violating this invariant.
        assertTrue(
            ok &&
            contractBalanceAfter == contractBalanceBefore - amount &&
            adversarialBalanceAfter == adversarialBalanceBefore + amount &&
            ownerBalanceAfter == ownerBalanceBefore
        );
    }
}

