        vm.assume(_target != address(0));
        vm.deal(address(c), _value);
        vm.deal(c.owner(), 0);
        uint256 balBefore = address(c).balance + _target.balance;
        vm.prank(c.owner());
        c.sendMoney(_target, _value);
        uint256 balAfter = address(c).balance + _target.balance;
        assertEq(balAfter, balBefore);
    }
}
